  ('TTD 25/13 - Llenado Integral - Monoposte - Aluminio'), ('TTD 40/13 - Llenado Integral - Monoposte - Aluminio'), ('TTD 63/13 - Llenado Integral - Monoposte - Aluminio'),
  ('TTD 100/13 - Llenado Integral - Monoposte - Aluminio'), ('TTD 125/13 - Llenado Integral - Monoposte - Aluminio'), ('TTD 160/13 - Llenado Integral - Monoposte - Aluminio'),
  ('TTD 200/13 - Llenado Integral - Monoposte - Aluminio'), ('TTD 250/13 - Llenado Integral - Monoposte - Aluminio'), ('TTD 160/13 - Llenado Integral - Monoposte - Cobre - TIPO EDENOR'),
  ('TTD 200/13 - Tanque Expansion - Plataforma - Cobre - TIPO DPEC'), ('TTD 315/13 - Tanque Expansion - Plataforma - Cobre - TIPO DPEC'), ('TTD 500/13 - Tanque Expansion - Plataforma - Cobre - TIPO DPEC'),
  ('TTD 630/13 - Tanque Expansion - Plataforma - Cobre - TIPO DPEC'), ('TTD 800/13 - Tanque Expansion - Plataforma - Cobre - TIPO DPEC'), ('TTD 160/13 - Tanque Expansion - Plataforma - Aluminio - TIPO DPEC'),
  ('TTD 200/13 - Tanque Expansion - Plataforma - Aluminio - TIPO DPEC'), ('TTD 315/13 - Tanque Expansion - Plataforma - Aluminio - TIPO DPEC'), ('TTD 16/33 - Llenado Integral - Monoposte - Cobre'),
  ('TTD 25/33 - Llenado Integral - Monoposte - Cobre'), ('TTD 40/33 - Llenado Integral - Monoposte - Cobre'), ('TTD 63/33 - Llenado Integral - Monoposte - Cobre'),
  ('TTD 100/33 - Llenado Integral - Monoposte - Cobre'), ('TTD 125/33 - Llenado Integral - Monoposte - Cobre'), ('TTD 160/33 - Llenado Integral - Monoposte - Cobre'),
  ('TTD 200/33 - Llenado Integral - Monoposte - Cobre'), ('TTD 250/33 - Llenado Integral - Monoposte - Cobre'), ('TTD 16/33 - Llenado Integral - Monoposte - Aluminio'),
  ('TTD 25/33 - Llenado Integral - Monoposte - Aluminio'), ('TTD 40/33 - Llenado Integral - Monoposte - Aluminio'), ('TTD 63/33 - Llenado Integral - Monoposte - Aluminio'),
  ('TTD 100/33 - Llenado Integral - Monoposte - Aluminio'), ('TTD 125/33 - Llenado Integral - Monoposte - Aluminio'), ('TTD 160/33 - Llenado Integral - Monoposte - Aluminio'),
  ('TTD 200/33 - Llenado Integral - Monoposte - Aluminio'), ('TTD 250/33 - Llenado Integral - Monoposte - Aluminio'), ('TTD 63/33 - Tanque Expansion - Plataforma - Aluminio - TIPO DPEC')
),
res (orden, seccion, metrica, valor, detalle) as (

  -- ---------- A. Catalogo en Supabase vs JSON del front ----------
  select 10, 'A. Catálogo en Supabase', 'Modelos en la tabla modelos',
         (select count(*) from modelos)::text, 'El JSON del front tiene 309'
  union all
  select 11, 'A. Catálogo en Supabase', 'Componentes en la tabla componentes',
         (select count(*) from componentes)::text, 'El JSON del front tiene 1725'
  union all
  select 12, 'A. Catálogo en Supabase', 'Componentes del JSON que FALTAN en la tabla',
         (select count(*) from cat c where c.tipo = 'componente'
            and not exists (select 1 from componentes x where x.codigo = c.codigo))::text,
         coalesce((select 'Primeros 40: ' || string_agg(codigo, ', ') from (
            select c.codigo from cat c where c.tipo = 'componente'
              and not exists (select 1 from componentes x where x.codigo = c.codigo)
            order by 1 limit 40) s),
         'Ninguno. La tabla está al día.')
  union all
  select 13, 'A. Catálogo en Supabase', 'Modelos del JSON que FALTAN en la tabla',
         (select count(*) from cat c where c.tipo = 'modelo'
            and not exists (select 1 from modelos x where x.codigo = c.codigo))::text,
         coalesce((select 'Primeros 40: ' || string_agg(codigo, ', ') from (
            select c.codigo from cat c where c.tipo = 'modelo'
              and not exists (select 1 from modelos x where x.codigo = c.codigo)
            order by 1 limit 40) s),
         'Ninguno. La tabla está al día.')

  -- ---------- B. Ordenes historicas ----------
  union all
  select 20, 'B. Órdenes históricas', 'Órdenes totales',
         (select count(*) from ordenes)::text, null
  union all
  select 21, 'B. Órdenes históricas', 'Órdenes que ya vienen de SAP (sap_abs_entry cargado)',
         (select count(*) from ordenes where sap_abs_entry is not null)::text,
         'Esperado: 0. Hoy no hay integración activa.'
  union all
  select 22, 'B. Órdenes históricas', 'Órdenes cuyo modelo coincide con un nombre del catálogo',
         (select count(*) from ordenes o where o.modelo in (select nombre from nombres))::text,
         'Como los 309 nombres coinciden con SAP, estas se vinculan sin pérdida'
  union all
  select 23, 'B. Órdenes históricas', 'Órdenes PROTOTIPO',
         (select count(*) from ordenes where modelo = 'PROTOTIPO')::text,
         'No tienen artículo en SAP por definición'
  union all
  select 24, 'B. Órdenes históricas', 'Órdenes con un modelo que NO está en el catálogo',
         (select count(*) from ordenes o where o.modelo <> 'PROTOTIPO'
            and o.modelo not in (select nombre from nombres))::text,
         coalesce((select 'Hasta 25 nombres: ' || string_agg(modelo, ' | ') from (
            select distinct o.modelo from ordenes o where o.modelo <> 'PROTOTIPO'
              and o.modelo not in (select nombre from nombres)
            order by 1 limit 25) s),
         'Ninguna.')

  -- ---------- C. Tareas historicas ----------
  union all
  select 30, 'C. Tareas históricas', 'Tareas totales',
         (select count(*) from tareas)::text, null
  union all
  select 31, 'C. Tareas históricas', 'Tareas sin componente asignado',
         (select count(*) from tareas where componente_codigo is null)::text,
         'Reparaciones, prototipos, tareas de área sin semielaborado'
  union all
  select 32, 'C. Tareas históricas', 'Tareas cuyo componente ESTÁ en el export de SAP',
         (select count(*) from tareas t join cat c on c.codigo = t.componente_codigo
            where c.en_sap)::text,
         'Estas sobreviven sin tocar nada'
  union all
  select 33, 'C. Tareas históricas', 'Tareas cuyo componente NO está en el export de SAP',
         (select count(*) from tareas t join cat c on c.codigo = t.componente_codigo
            where not c.en_sap)::text,
         coalesce((select 'Por familia: ' || string_agg(f || ' ' || n, ' · ' order by n desc) from (
            select left(t.componente_codigo, 6) f, count(*) n
            from tareas t join cat c on c.codigo = t.componente_codigo
            where not c.en_sap group by 1) s),
         'Ninguna.')
  union all
  select 34, 'C. Tareas históricas', 'Tareas con un componente que no está ni en el catálogo de la PWA',
         (select count(*) from tareas t where t.componente_codigo is not null
            and not exists (select 1 from cat c where c.codigo = t.componente_codigo))::text,
         coalesce((select 'Hasta 25: ' || string_agg(componente_codigo, ', ') from (
            select distinct t.componente_codigo from tareas t where t.componente_codigo is not null
              and not exists (select 1 from cat c where c.codigo = t.componente_codigo)
            order by 1 limit 25) s),
         'Ninguna.')
  union all
  select 35, 'C. Tareas históricas', 'Componentes distintos usados por el histórico',
         (select count(distinct componente_codigo) from tareas)::text, null

  -- ---------- D. Otros activos historicos que dependen del catalogo ----------
  union all
  select 40, 'D. Otros activos históricos', 'Paradas registradas',
         (select count(*) from paradas)::text, 'Demoras, causas, tiempos muertos'
  union all
  select 41, 'D. Otros activos históricos', 'Tiempos estándar del asistente de mejora continua',
         (select count(*) from tiempos_estandar)::text, 'Aprenden de la mediana histórica. Se reinician si se borra el histórico'
  union all
  select 42, 'D. Otros activos históricos', 'Planos cargados por componente',
         coalesce((select case when reltuples < 0 then 'sin estadística aún' else 'aprox. ' || reltuples::bigint::text end
                   from pg_class where oid = to_regclass('public.planos')), 'la tabla no existe'), 'Atados a componente_codigo. Valor aproximado (estadística de Postgres) para no fallar si la tabla no existe'
)
select seccion, metrica, valor, detalle
from res
order by orden;
